  "in.d.checks": ["Ver todas las comprobaciones ({ok} de {n} correctas)", "See all checks ({ok} of {n} passed)", "Ver todas as verificações ({ok} de {n} corretas)"],
  "in.samples_sub": ["Son archivos reales en formato Conduto. Cada uno muestra una situación distinta.", "These are realistic files in Conduto's formats. Each one shows a different situation.", "São arquivos realistas nos formatos da Conduto. Cada um mostra uma situação diferente."],
  "in.shows.legacy_workbook": ["Muestra: un formato antiguo que nunca vimos, con nombres abreviados y errores. El sistema lo entiende, aprende el formato y suma el proyecto a los benchmarks.", "Shows: an old format we have never seen, with abbreviated and misspelled names. The system understands it, learns the format and adds the project to the benchmarks.", "Mostra: um formato antigo nunca visto, com nomes abreviados e erros. O sistema entende, aprende o formato e soma o projeto aos benchmarks."],
  "in.shows.change_order_pdf": ["Muestra: se leen el número, el monto y la causa del PDF, y se comprueba que cada valor aparece en el documento.", "Shows: the number, amount and cause are read from the PDF, and each value is checked against the document.", "Mostra: número, valor e causa são lidos do PDF, e cada valor é conferido no documento."],
  "in.shows.scanned_pdf": ["Muestra: un PDF escaneado sin texto. El sistema no inventa datos: lo detecta y lo aparta.", "Shows: a scanned PDF with no text. The system does not make data up: it detects it and sets it aside.", "Mostra: um PDF digitalizado sem texto. O sistema não inventa dados: detecta e separa."],
  "in.shows.schedule_xml": ["Muestra: una nueva versión del cronograma. Se ve qué tareas se movieron y cómo cambia la fecha de fin.", "Shows: a new schedule version. You see which tasks moved and how the finish date changes.", "Mostra: uma nova versão do cronograma. Vê-se quais tarefas mudaram e como muda a data de término."],
  "in.shows.cost_workbook": ["Muestra: el control de costos mensual de un proyecto, reconocido con su formato.", "Shows: a project's monthly cost control, recognized by its format.", "Mostra: o controle de custos mensal de um projeto, reconhecido pelo formato."],
